public enum SwiftUtilities {
    public static func clamp<T: Comparable>(_ value: T, lower: T, upper: T) -> T {
        precondition(lower <= upper, "lower must not exceed upper")
        return min(max(value, lower), upper)
    }

    public static func firstNonEmpty<S: Sequence>(_ values: S) -> S.Element? where S.Element: StringProtocol {
        values.first { !$0.isEmpty }
    }
}

print(SwiftUtilities.clamp(12, lower: 0, upper: 10))
print(SwiftUtilities.firstNonEmpty(["", "Swift", "CodeLeaf"]) ?? "none")
